function isEmptyHTMLString(e) {
  e = e.replace(/<br \/>/g, "\n");
  e = e.replace(/<br>/g, "\n");
  e = e.replace(/(<div[^>]+?>|<div>|<\/div>)/g, "");
  e = e.replace(/(<p[^>]+?>|<p>|<\/p>)/g, "");
  e = e.replace(/(<span[^>]+?>|<span>|<\/span>)/g, "");
  e = e.replace(/(<i>|<\/i>)/g, "");
  e = e.replace(/(<u>|<\/u>)/g, "");
  e = e.replace(/(<b>|<\/b>)/g, "");
  e = e.replace(/(<blockquote>|<\/blockquote>)/g, "");
  e = e.replace(/(<sub>|<\/sub>)/g, "");
  e = e.replace(/(<sup>|<\/sup>)/g, "");
  e = e.replace(/\u200B/g, "");
  e = e.replace(/&lt;/g, "<");
  e = e.replace(/&gt;/g, ">");
  e = e.replace(/&nbsp;/g, "");
  e = e.replace(/^\s*|\s*$/g, "");
  if (e == "") {
    return true;
  } else {
    return false;
  }
}
