function sendAjaxRequestWO(e, t, s) {
  reqWO2PO = getXMLHttpRequest();
  if (reqWO2PO) {
    if (typeof s === "undefined") {
      s = "POST";
    }
    reqWO2PO.open(s, e, true);
    reqWO2PO.setRequestHeader(
      "Content-type",
      "application/x-www-form-urlencoded;charset=UTF-8",
    );
    reqWO2PO.onreadystatechange = handleAjaxRequestStateChangeWO;
    reqWO2PO.send(t);
  }
}
function handleAjaxRequestStateChangeWO() {
  if (reqWO2PO.readyState == 4) {
    if (reqWO2PO.status == 200) {
      if ("associate_po" == operationWO2PO) {
        var e = reqWO2PO.responseXML.childNodes[0];
        var t = e.childNodes[0].childNodes[0].nodeValue;
        if (t == "200") {
          window.showalert(
            "success",
            getMessageForKey("sdp.workorder.wotopo.associate.success"),
            "isAutoHide=true",
          );
        } else {
          window.showalert(
            "failure",
            getMessageForKey("sdp.workorder.wotopo.associate.failure"),
            "isAutoHide=true",
          );
        }
        window.setTimeout(function () {
          window.opener.$req.details.updateRequestTemplates("purchase");
          window.close();
        }, 500);
      } else if ("detach_po" == operationWO2PO) {
        var e = reqWO2PO.responseXML.childNodes[0];
        var t = e.childNodes[0].childNodes[0].nodeValue;
        if (t == "200") {
          window.showalert(
            "success",
            getMessageForKey("sdp.workorder.wotopo.detach.success"),
            "isAutoHide=true",
          );
        } else {
          window.showalert(
            "failure",
            getMessageForKey("sdp.workorder.wotopo.detach.failure"),
            "isAutoHide=true",
          );
        }
        jQuery(
          document.getElementById(
            "associatedPurchaseItemDetails" + operationPurchaseOrderId,
          ),
        ).fadeOut(400, function () {
          jQuery(
            "#associatedPurchaseItemDetails" + operationPurchaseOrderId,
          ).remove();
        });
        window.opener.$req.details.updateRequestTemplates("purchase");
        if (
          jQuery(document.getElementById("associatedpurchaseItem")).children()
            .length == 1
        ) {
          window.setTimeout(function () {
            window.close();
          }, 500);
        }
      } else if ("open_po_printview" == operationWO2PO) {
        if (
          jQuery(document.getElementById("associatedPurchaseDetails")).length >
          0
        ) {
          document.getElementById("associatedPurchaseDetails").style.display =
            "none";
          jQuery(document.getElementById("PurchaseHeaderInSRDetailsPage")).text(
            getMessageForKey("sdp.workorder.wotopo.po.details.header"),
          );
          document.getElementById("associatedPOdetailsHeader").style.display =
            "block";
        } else {
          document.getElementById("listview_div").style.display = "none";
        }
        document.getElementById("details_div").style.display = "block";
        document.getElementById("details_content").innerHTML =
          reqWO2PO.responseText;
      }
    }
  }
}
