function canCalHeight(e, t, s) {
  var a = t.css("display");
  if (a === "none") {
    e.css("display", "none");
  } else {
    e.css("display", "block");
  }
  var i = false;
  if (a === "none") {
    i = false;
  } else {
    i = true;
  }
  return i;
}
function setHeight(e) {
  var t = e ? "#WOResourceForm .viewtype_1" : "#WOResourceDetails .viewtype_1";
  var s = jQuery(t);
  if (s.length > 0) {
    var a = 0;
    var i;
    i = s.children("div.resourceportlet").length;
    while (i > a) {
      var n = s.find("div[resorder=resourceportlet" + a + "]");
      var r = n.find(".spacediv");
      r.css("height", "");
      var o = canCalHeight(n, r, e);
      var l = isExpanded(n, e);
      if (!o || l) {
        a++;
        continue;
      }
      var d, c, u, m;
      u = r;
      d = u.height();
      a++;
      if (a >= i) {
        break;
      }
      n = s.find("div[resorder=resourceportlet" + a + "]");
      r = n.find(".spacediv");
      var p = canCalHeight(n, r, e);
      while (!p && a < i) {
        a++;
        n = s.find("div[resorder=resourceportlet" + a + "]");
        r = n.find(".spacediv");
        p = canCalHeight(n, r, e);
      }
      var f = isExpanded(n, e);
      var g = false;
      if (!f) {
        m = s.find("div[resorder=resourceportlet" + a + "] .spacediv");
        m.css("height", "");
        c = m.height();
        if (d >= c) {
          m.height(d);
          u.height(d);
        } else {
          u.height(c);
          m.height(c);
        }
        a++;
      }
    }
  }
}
function isExpanded(e, t) {
  var s = false;
  if (e.hasClass("shrink") || e.hasClass("col-xs-12")) {
    s = true;
  }
  return s;
}
