function setPeriodicCalendarDate(e) {
  var t;
  if (e.id == "threemonths") {
    t = 90;
  } else if (e.id == "sixmonths") {
    t = 180;
  } else if (e.id == "ninemonths") {
    t = 270;
  }
  var s = document.getElementById("reviewdate").value;
  var a = document.getElementById("reviewdate_Display").value;
  var i = new Date();
  i.setHours(12, 0, 0);
  i.setMilliseconds(0);
  i.setDate(i.getDate() + t);
  document.getElementById("reviewdate").value = i.getTime();
  var n = "reviewdate";
  compareElement = "expirydate";
  errorCondition = "";
  errorMsg = getMessageForKey("sdp.solution.expiry.review.date.mismatch1");
  if (checkValidDate(n, compareElement, errorMsg, errorCondition)) {
    document.getElementById("reviewdate").value = i.getTime();
    displayClientTime("reviewdate");
    jQuery("#reviewDateMenu")
      .find("span")
      .html(document.getElementById("reviewdate_Display").value);
  } else {
    document.getElementById("reviewdate").value = s;
    document.getElementById("reviewdate_Display").value = a;
    if (s != null && s != "" && s != "-1") {
      jQuery("#reviewDateMenu")
        .find("span")
        .html(document.getElementById("reviewdate_Display").value);
    } else {
      resetReviewDate();
    }
  }
}
