function escapeJSONString(e) {
  e = e.replace(/&quot;/g, '\\"');
  e = e.replace(/&#39;/g, '\\"');
  e = e.replace(/#/g, "@@hash@@");
  e = e.replace(/&/g, "@@ampersand@@");
  e = e.replace(/%/g, "@@percentage@@");
  e = e.replace(/</g, "@@leftarrow@@");
  e = e.replace(/>/g, "@@rightarrow@@");
  e = e.replace(/\?/g, "@@question@@");
  return e;
}
