function callSLAAjax(e, t) {
  req = getXMLHttpRequest();
  if (req) {
    if (e == "Delete") {
      if (!checkForRowSelection(document.forms[t], "checkbox")) {
        alert(getMessageForKey("sdp.admin.common.deletemess"));
        return false;
      }
      var s = confirm(getMessageForKey("sdp.setup.sla.confirm"));
      if (!s) {
        return;
      }
      var a = "/SLADef.do";
      var i = "mode=delete" + getCSRFParamURL();
      var n = getSelectedCheckBoxes(document.forms[t]);
      for (var r = 0; r < n.length; r++) {
        i += "&slaID=" + encodeURIComponent(n[r]);
      }
      i = appendParameter(i, getCSRFParamName(), getCSRFParamValue());
      req.open("POST", a, true);
      req.setRequestHeader(
        "Content-type",
        "application/x-www-form-urlencoded;charset=UTF-8",
      );
      req.setRequestHeader("Content-length", i.length);
      req.onreadystatechange = function () {
        deleteSLA(t);
      };
      req.send(i);
    }
  } else {
    alert("Your browser doesnot support this");
  }
}
function deleteSLA(e) {
  if (req.readyState == 4) {
    if (req.status == 200) {
      var t = req.responseXML;
      var s = t.childNodes[0].childNodes[0].childNodes[0].nodeValue;
      if (s == 200 || s == 300) {
        var a =
          req.responseXML.getElementsByTagName("MESSAGE")[0].childNodes[0]
            .nodeValue;
        updateState(getPortalViewName(e), "_D_RP", null);
        parent.refreshSubView(parent.getPortalViewName(e));
        showSuccessMessageAndClose(null, a, 2e3);
      }
    } else {
      showFailureMessageAndClose(null, "Unable to get details", 2e3);
    }
  }
}
