function validateImage() {
  var e = $("serviceCatLogo").value;
  var t = e.toString();
  var s = 0;
  var a = t.length;
  var i = a - 1;
  var n = a - 2;
  var r = a - 3;
  var o = a - 4;
  var l = t.lastIndexOf(".");
  var d = t.length;
  var c = t.substring(l, d);
  if (c == ".gif" || c == ".GIF" || c == ".Gif") {
    return true;
  } else if (c == ".jpg" || c == ".JPG" || c == ".Jpg") {
    return true;
  } else if (c == ".png" || c == ".PNG" || c == ".Png") {
    return true;
  } else if (c == ".wmf" || c == ".WMF" || c == ".Wmf") {
    return true;
  } else if (c == ".pcx" || c == ".PCX" || c == ".Pcx") {
    return true;
  } else if (c == ".tiff" || c == ".TIFF" || c == ".Tiff") {
    return true;
  } else if (c == ".jpeg" || c == ".JPEG" || c == ".Jpeg") {
    return true;
  } else {
    alert(getMessageForKey("sdp.setup.orgdef.image.format.jserror"));
    return false;
  }
}
