function checkProxySettings(e) {
  if (e.proxyHost.value == null || e.proxyHost.value.trim() == "") {
    alert(
      getMessageForKey("sdp.admin.proxysettings.validation.mandatory", [
        getMessageForKey("sdp.admin.proxy.host"),
      ]),
    );
    e.proxyHost.focus();
    return;
  }
  if (e.proxyPort.value == null || e.proxyPort.value.trim() == "") {
    alert(
      getMessageForKey("sdp.admin.proxysettings.validation.mandatory", [
        getMessageForKey("sdp.admin.proxy.port"),
      ]),
    );
    e.proxyPort.focus();
    return;
  } else if (!checkNumeric(e.proxyPort, "int", false)) {
    return;
  }
  var t = e.proxyPassword.value;
  if (jQuery("#proxyPwdChanged").length) {
    if (checkProxyOldValues(e)) {
      showconfirm(
        true,
        "title=" +
          getMessageForKey("admin.proxy.update.title") +
          ", message=" +
          getMessageForKey("admin.proxy.update.confirmation") +
          ", submitbutton=" +
          getMessageForKey("sdp.common.update") +
          ", cancelbutton=" +
          getMessageForKey("sdp.common.cancel") +
          ", closebutton=yes, closeOnEscKey=yes",
        s,
      );
      function s(s) {
        if (s) {
          if (t != null && t.trim() != "") {
            e.proxyPassword.value = encryptDataWithRSA(t);
          }
          addUpdateProxySettings(e);
        }
      }
    }
  } else {
    if (t != null && t.trim() != "") {
      e.proxyPassword.value = encryptDataWithRSA(t);
    }
    addUpdateProxySettings(e);
  }
}
