function checkUDFLongValue(e) {
  re = /^[0-9\s]+$/;
  if (re.test(e)) {
    return true;
  } else {
    return false;
  }
}
function checkUDFDecimalValue(e) {
  if (isDecimal(e) == false) {
    return false;
  }
  var t = trimAll(e);
  var s = t;
  if (t.startsWith("-")) {
    s = t.toString().split("-");
    s = s[1];
  }
  if (t.startsWith("+")) {
    s = t.toString().split("+");
    s = s[1];
  }
  s = s.replace(/^[0]+/g, "");
  var a = e.split(".");
  if (a[0] == null || a[0] == "") {
    a[0] = 0;
  }
  if (a[0].length > 13) {
    return false;
  }
  return true;
}
var truncate = {
  more: function (e) {
    var t = e.parentNode.getAttribute("data-before");
    var s = e.parentNode.getAttribute("data-after");
    if (e.parentNode.classList.contains("truncate-ellipsis")) {
      e.parentNode.classList.remove("truncate-ellipsis");
      e.text = s;
      e.classList.remove("right0");
      e.classList.remove("top0");
    } else {
      e.parentNode.classList.add("truncate-ellipsis");
      e.text = t;
      e.classList.add("right0");
      e.classList.add("top0");
    }
  },
  countlines: function (e) {
    var t = e.style.lineHeight;
    var s = 1e3;
    e.style.lineHeight = s + "px";
    var a = e.getBoundingClientRect().height;
    e.style.lineHeight = t;
    return Math.floor(a / s);
  },
  ellipsis: function (e) {
    var t = truncate.countlines(e);
    if (t > 1) {
      e.classList.add("truncate-ellipsis");
      e.querySelector("a").classList.remove("hide");
      var s = e.querySelector("a").clientWidth;
      if (jQuery.fn.getDirection() === "ltr") {
        e.style.paddingRight = s + "px";
      } else if (jQuery.fn.getDirection() === "rtl") {
        e.style.paddingLeft = s + "px";
      }
    }
  },
  ellipsisall: function () {
    var e = document.querySelector("[data-name=ruleemail]");
    e = e.querySelectorAll("[data-id=truncate-ellipsis]");
    for (var t = 0; t < e.length; t++) {
      truncateellipsis(e[t]);
    }
  },
};
