function getData() {
  if (req1.readyState == 4) {
    if (req1.status == 200) {
      var e = "";
      var t = 0;
      var s = req1.responseText;
      s = s.replace(/{/g, "");
      s = s.replace(/}/g, "");
      value1 = s.split("&");
      for (j = 0; j < value1.length; j++) {
        value2 = value1[j].split("~");
        if (value2[0] == "Stat") {
          value3 = value2[1].split(",");
          for (i = 0; i < value3.length; i++) {
            t = value3[i].split("=")[1];
            if (value3[i].split("=")[0].match("Pending")) {
              if (t != null && t != "") {
                document.getElementById("pendRequestCnt").innerHTML =
                  encodeHTML(t);
              }
            } else if (value3[i].split("=")[0].match("Completed")) {
              if (t != null && t != "") {
                document.getElementById("compRequestCnt").innerHTML =
                  encodeHTML(t);
              }
            }
          }
          document.getElementById("requestCnt").innerHTML =
            Number(document.getElementById("pendRequestCnt").innerHTML) +
            Number(document.getElementById("compRequestCnt").innerHTML);
        } else if (value2[0] == "SLA") {
          value3 = value2[1].split(",");
          for (i = 0; i < value3.length; i++) {
            t = value3[i].split("=")[1];
            if (!value3[i].split("=")[0].match("Not Violated")) {
              if (t != null && t != "") {
                document.getElementById("slaViolatedCnt").innerHTML =
                  encodeHTML(t);
              }
            }
          }
        }
      }
    } else {
      alert("Problem: " + req1.statusText);
    }
  }
}
