  saveInlineEditChanges: function (e, t, s) {
    var a = e[0].entity_id,
      i = e[0].fieldid,
      n = {},
      r = e[0].field,
      o = {};
    if (e[0].type == "select" || e[0].type == "lookup") {
      o[r] = i && i != "" ? { id: i } : null;
    } else {
      o[r] = i && i != "null" ? { value: i } : null;
    }
    n[s.t_obj.options.inlineEditEntity] = o;
    var l = "";
    if (t.isUnifiedView) {
      var d = s.loadedRecords[a].task;
      var c = d.associated_entity != "general" ? d[d.associated_entity].id : "";
      l = $tasks.getEntityURL(
        d.associated_entity,
        c,
        d.associated_entity === "milestone" ? d["project"].id : "",
        a,
      );
    } else {
      l = s.loadedRecords[a].baseURL + "/" + a;
    }
    sdpAjax({
      url: "/api/v3/" + l,
      type: "PUT",
      data: sdpAjaxInputData(n),
      acceptODCompatible: true,
      async: false,
      ignorefailuremessage: n.task.status ? true : false,
      success: function (t) {
        if (n.task.status && jQuery.isArray(t.response_status)) {
          $tasks.successMessageHandling(
            t,
            window.translate("sdp.project.history.closetask0"),
          );
          return;
        }
        var a = "";
        if (t.response_status.messages) {
          a = t.response_status.messages[0].message;
        } else {
          a = translate("api.updated.success", [translate("common.task")]);
        }
        showalert("success", a, "isAutoHide=true");
        s.refreshTable();
        if (e[0].field == "status") {
          if (
            $taskList.taskOptions &&
            ($taskList.taskOptions.module == "release" ||
              $taskList.taskOptions.module == "change")
          ) {
            window.top.$rc.refreshLeftPanelCount("task");
          }
          if (
            $taskList.taskOptions &&
            $taskList.taskOptions.module == "problem"
          ) {
            window.top.$problemDetails.refreshRightSectionProperties("tasks");
          }
        }
      },
      error: function (e) {
        var t =
          e.responseJSON.response_status.messages &&
          e.responseJSON.response_status.messages[0].field;
        if (
          t &&
          [
            "scheduled_start_time",
            "scheduled_end_time",
            "actual_start_time",
            "actual_end_time",
          ].indexOf(t) > -1
        ) {
          var s =
            t === "scheduled_start_time" || t === "scheduled_end_time"
              ? "api.validation.scheduledstart.scheduledend"
              : "api.validation.actualstart.actualend";
          showalert("failure", translate(s), "isAutoHide=false");
        }
        var a =
          e.responseJSON.response_status.messages &&
          e.responseJSON.response_status.messages[0];
        if (a.status_code >= 6e4 && a.status_code <= 60006) {
          showalert("failure", translate(a.message), "isAutoHide=false");
        }
      },
    });
  },
