  getEntityTasks: function () {
    var e = {
      sort_order: "asc",
      sort_field: "index",
      row_count: "100",
      start_index: 1,
      fields_required: ["id", "title"],
    };
    if (
      $taskList.taskOptions.module == "release" ||
      $taskList.taskOptions.module == "change"
    ) {
      e.search_criteria = {
        field: "stage",
        value: $taskList.taskOptions.stageId,
        condition: "is",
      };
    }
    var t = [],
      s = true;
    while (s) {
      sdpAjax({
        url: "/api/v3/" + table_comp_task.t_obj.options.callbackURL,
        async: false,
        acceptODCompatible: true,
        data: sdpAjaxInputData({ list_info: e }),
        success: function (a) {
          t = t.concat(a["tasks"]);
          if (a.list_info && a.list_info.has_more_rows == true) {
            e.start_index = t.length + 1;
          } else {
            s = false;
          }
        },
        error: function () {
          s = false;
        },
      });
    }
    var a = jQuery("#organize-tasks");
    a.html("");
    jQuery.each(t, function (e, t) {
      a.append(
        "<li data-task-id=" +
          t.id +
          '><div class="text-overflow w-420px"><span class="cspr drag1 icon-xs ml20 mr5 cursor-move top-1"></span><span class="p5 fw" rel="uitip" mode_ellipsis="true" title="' +
          e_attr(t.title) +
          '">' +
          e_html(t.title) +
          "</span></div></li>",
      );
    });
  },
